// Pedal pictures: small pictures in colour for the FX editor's header, line drawings (A8 masks) for the FX tiles.
// fx_pedals.c is generated by tools/gen_pedals.py from private pictures; without them it has no entries.
#pragma once

#include <stdint.h>

#include "lvgl.h"

// Picture of a model (FxTypeValue type), NULL if there is none.
const lv_image_dsc_t *nano_fx_pedal(uint32_t type);

// Line drawing of the pedal for the FX tiles (at the tile's right edge; a wide device is cut off there), NULL if
// there is none.
const lv_image_dsc_t *nano_fx_pedal_tile(uint32_t type);

// The name the own build shows for a model (the modelled device), NULL = its model name. The published build has none.
const char *nano_fx_real_name(uint32_t type);
